Testing CORS Configuration
To verify CORS configuration, ensure that your Angular application is running on
http://localhost:4200 and make requests to your ASP.NET Core Web API. Check the network
requests in your browser’s developer tools to ensure that the CORS headers are correctly set.
Example Request:
Using Angular’s HttpClient to make a request:
import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
@Injectable({
providedIn: 'root'
})
export class ApiService {
private apiUrl = 'https://localhost:5001/api/products';
constructor(private http: HttpClient) { }
getProducts() {
return this.http.get(this.apiUrl);
}
}
